<?php
declare(strict_types=1);

/**
 * install_mrl_team_profile_production.php
 *
 * VERSION: v001
 * LAST MODIFIED: 8/27/2026 10:16:02 pm
 *
 * PURPOSE:
 * Joint production promotion of the tested Team + Profile redesign.
 *
 * EXPECTED LIVE BASELINES:
 * - production team.php VERSION: v034
 * - production profile.php exact uploaded baseline
 * - team_redesign.php VERSION: v011 exact tested baseline
 * - profile_redesign.php VERSION: v003 exact tested baseline
 *
 * OUTPUT:
 * - production team.php VERSION: v035
 * - production profile.php VERSION: v003
 *
 * SAFETY:
 * - exact SHA-256 checks for all four source/target baselines
 * - verifies /mrl_team support files before any write
 * - backs up both production pages before replacing either one
 * - writes productionized complete files, not renames or partial patches
 * - if either production write/postflight fails, automatically restores BOTH production backups
 * - redesign source files, JSON, Content Manager and theme helper are never modified
 * - legacy change-login-email.php / change-second-email.php are left on disk for reference
 *
 * CHANGELOG:
 *
 * v001 (8/27/2026 10:16:02 pm)
 * - PRODUCTION: Promotes Team redesign v011 and Profile redesign v003 together.
 * - TEAM: Production version becomes team.php v035.
 * - PROFILE: Production version becomes profile.php v003.
 * - LINKS: Removes redesign-test labels and points Team/Profile links to production names.
 */

date_default_timezone_set('America/New_York');

const EXPECTED_PROD_TEAM_SHA256 = 'ea4542182638143549230d4b47ec51e6148ff018d0a799c1a8c7af0971cfcdfc';
const EXPECTED_PROD_PROFILE_SHA256 = 'a37db5b07b3524d7b0eef736bcfa89876afdd0e5a531c52764e2f629e54fa32d';
const EXPECTED_TEAM_REDESIGN_SHA256 = '08002c9a4bb666a379971f058ced5a81c3b0e6df0c8f15cde96c1fc142e05140';
const EXPECTED_PROFILE_REDESIGN_SHA256 = 'af7e53ce3183420ebf8ad3edc09a80be963807d8cd64aa99a3dfbc7175060bad';

$base = __DIR__;

$prodTeam = $base . '/team.php';
$prodProfile = $base . '/profile.php';
$teamRedesign = $base . '/team_redesign.php';
$profileRedesign = $base . '/profile_redesign.php';

$json = $base . '/mrl_team/mrl_team_page_content.json';
$manager = $base . '/mrl_team/admin_team_page_content.php';
$helper = $base . '/mrl_team/mrl_theme_helper.php';

$legacyLogin = $base . '/change-login-email.php';
$legacySecond = $base . '/change-second-email.php';

function ih(string $v): string
{
    return htmlspecialchars($v, ENT_QUOTES, 'UTF-8');
}

function status_row(string $label, bool $ok, string $detail = ''): void
{
    echo '<tr><td>' . ih($label) . '</td><td class="' . ($ok ? 'ok' : 'bad') . '">'
        . ($ok ? 'PASS' : 'FAIL') . '</td><td>' . ih($detail) . '</td></tr>';
}

function atomic_write(string $path, string $data): bool
{
    $tmp = $path . '.tmp_' . bin2hex(random_bytes(4));

    if (file_put_contents($tmp, $data, LOCK_EX) === false) {
        return false;
    }

    if (!@rename($tmp, $path)) {
        @unlink($tmp);
        return false;
    }

    return true;
}

function restore_pair(string $prodTeam, string $prodProfile, string $backupDir, array &$messages): bool
{
    $teamBackup = $backupDir . '/team.php';
    $profileBackup = $backupDir . '/profile.php';

    $ok = true;

    if (!is_file($teamBackup) || !copy($teamBackup, $prodTeam)) {
        $messages[] = 'ROLLBACK ERROR: Could not restore production team.php.';
        $ok = false;
    } else {
        $messages[] = 'ROLLBACK: Restored production team.php.';
    }

    if (!is_file($profileBackup) || !copy($profileBackup, $prodProfile)) {
        $messages[] = 'ROLLBACK ERROR: Could not restore production profile.php.';
        $ok = false;
    } else {
        $messages[] = 'ROLLBACK: Restored production profile.php.';
    }

    return $ok;
}

$teamReplacement = base64_decode('', true);
$profileReplacement = base64_decode('', true);

$replacementOk =
    is_string($teamReplacement)
    && is_string($profileReplacement)
    && strpos($teamReplacement, 'VERSION: v035') !== false
    && strpos($profileReplacement, 'VERSION: v003') !== false
    && strpos($teamReplacement, 'profile_redesign.php') === false
    && strpos($teamReplacement, 'team_redesign.php') === false
    && strpos($profileReplacement, '/team_redesign.php') === false
    && strpos($profileReplacement, 'profile_redesign.php') === false
    && strpos($teamReplacement, 'redesign test') === false
    && strpos($profileReplacement, 'redesign test') === false;

$prodTeamExists = is_file($prodTeam);
$prodProfileExists = is_file($prodProfile);
$teamRedesignExists = is_file($teamRedesign);
$profileRedesignExists = is_file($profileRedesign);

$prodTeamHash = $prodTeamExists ? hash_file('sha256', $prodTeam) : '';
$prodProfileHash = $prodProfileExists ? hash_file('sha256', $prodProfile) : '';
$teamRedesignHash = $teamRedesignExists ? hash_file('sha256', $teamRedesign) : '';
$profileRedesignHash = $profileRedesignExists ? hash_file('sha256', $profileRedesign) : '';

$prodTeamOk = $prodTeamExists
    && $prodTeamHash === EXPECTED_PROD_TEAM_SHA256
    && strpos((string)file_get_contents($prodTeam), 'VERSION: v034') !== false;

$prodProfileOk = $prodProfileExists
    && $prodProfileHash === EXPECTED_PROD_PROFILE_SHA256;

$teamRedesignOk = $teamRedesignExists
    && $teamRedesignHash === EXPECTED_TEAM_REDESIGN_SHA256
    && strpos((string)file_get_contents($teamRedesign), 'VERSION: v011') !== false;

$profileRedesignOk = $profileRedesignExists
    && $profileRedesignHash === EXPECTED_PROFILE_REDESIGN_SHA256
    && strpos((string)file_get_contents($profileRedesign), 'VERSION: v003') !== false;

$supportFiles = [$json, $manager, $helper];
$supportHashesBefore = [];
$supportOk = true;

foreach ($supportFiles as $path) {
    if (!is_file($path)) {
        $supportOk = false;
        $supportHashesBefore[$path] = '';
    } else {
        $supportHashesBefore[$path] = hash_file('sha256', $path);
    }
}

$jsonOk = false;
$panelCounts = [];

if (is_file($json)) {
    $raw = file_get_contents($json);
    $decoded = is_string($raw) ? json_decode($raw, true) : null;

    if (is_array($decoded)) {
        $jsonOk = true;

        foreach (['admin_league_panel','admin_hosting_panel','league_panel','team_panel'] as $key) {
            $items = $decoded[$key]['items'] ?? null;
            $panelCounts[$key] = is_array($items) ? count($items) : -1;

            if ($panelCounts[$key] < 0) {
                $jsonOk = false;
            }
        }
    }
}

$legacyPagesPresent = is_file($legacyLogin) && is_file($legacySecond);

$apply = isset($_POST['apply']) && $_POST['apply'] === '1';
$messages = [];
$success = false;

if ($apply && $replacementOk && $prodTeamOk && $prodProfileOk
    && $teamRedesignOk && $profileRedesignOk && $supportOk && $jsonOk) {

    $backupDir = $base . '/_migration_backups/team_profile_production_' . date('Ymd_His');
    $ok = (is_dir($backupDir) || mkdir($backupDir, 0755, true));

    if (!$ok) {
        $messages[] = 'Could not create production backup directory.';
    }

    if ($ok && !copy($prodTeam, $backupDir . '/team.php')) {
        $ok = false;
        $messages[] = 'Could not back up production team.php.';
    }

    if ($ok && !copy($prodProfile, $backupDir . '/profile.php')) {
        $ok = false;
        $messages[] = 'Could not back up production profile.php.';
    }

    if ($ok) {
        $messages[] = 'Backed up BOTH production pages before any replacement.';
    }

    // Write Team first, Profile second. Any failure rolls both back.
    if ($ok && !atomic_write($prodTeam, $teamReplacement)) {
        $ok = false;
        $messages[] = 'Could not install production team.php v035.';
    } elseif ($ok) {
        $messages[] = 'Installed production team.php v035.';
    }

    if ($ok && !atomic_write($prodProfile, $profileReplacement)) {
        $ok = false;
        $messages[] = 'Could not install production profile.php v003.';
    } elseif ($ok) {
        $messages[] = 'Installed production profile.php v003.';
    }

    if ($ok) {
        $installedTeam = (string)file_get_contents($prodTeam);
        $installedProfile = (string)file_get_contents($prodProfile);

        $checks = [
            'Team v035 header' => strpos($installedTeam, 'VERSION: v035') !== false,
            'Team production profile link' => strpos($installedTeam, 'profile.php') !== false
                && strpos($installedTeam, 'profile_redesign.php') === false,
            'Team no redesign label' => strpos($installedTeam, 'redesign test') === false,
            'Team four-panel JSON loader' => strpos($installedTeam, 'foreach ($teamPageContentPanelKeys as $panelKey)') !== false,
            'Team Cars theme' => strpos($installedTeam, 'mrl-theme-cars') !== false,
            'Team Starry Night theme' => strpos($installedTeam, 'mrl-theme-starry-night') !== false,
            'Team Dark theme' => strpos($installedTeam, 'mrl-theme-dark') !== false,
            'Team Light theme' => strpos($installedTeam, 'mrl-theme-light') !== false,
            'Team normal pick route' => strpos($installedTeam, 'include $currentForm;') !== false,
            'Team LP route' => strpos($installedTeam, "include 'team-late-pick.php';") !== false,
            'Team RP/RD route' => strpos($installedTeam, "include 'team_replacement_driver.php';") !== false,
            'Team current chart' => strpos($installedTeam, "include 'current_segment_chart.php';") !== false,
            'Team prior-year charts' => strpos($installedTeam, "include 'prior_year_user_team_chart.php';") !== false,
            'Profile v003 header' => strpos($installedProfile, 'VERSION: v003') !== false,
            'Profile production Team link' => strpos($installedProfile, '/team.php') !== false
                && strpos($installedProfile, '/team_redesign.php') === false,
            'Profile no redesign label' => strpos($installedProfile, 'redesign test') === false,
            'Profile authenticated identity' => strpos($installedProfile, 'userSession') !== false,
            'Profile Login Email action' => strpos($installedProfile, 'save_primary_email') !== false,
            'Profile Secondary Email action' => strpos($installedProfile, 'save_secondary_email') !== false,
            'Profile Theme action' => strpos($installedProfile, 'save_theme') !== false,
            'Profile CSRF protection' => strpos($installedProfile, 'mrl_profile_csrf') !== false,
        ];

        foreach ($checks as $label => $passed) {
            $messages[] = ($passed ? 'PASS: ' : 'FAIL: ') . $label;
            if (!$passed) {
                $ok = false;
            }
        }
    }

    // Source redesign files and support files must remain byte-for-byte unchanged.
    if ($ok) {
        $sourceChecks = [
            'team_redesign.php unchanged' =>
                hash_file('sha256', $teamRedesign) === EXPECTED_TEAM_REDESIGN_SHA256,
            'profile_redesign.php unchanged' =>
                hash_file('sha256', $profileRedesign) === EXPECTED_PROFILE_REDESIGN_SHA256,
        ];

        foreach ($supportHashesBefore as $path => $hash) {
            $sourceChecks[str_replace($base . '/', '', $path) . ' unchanged'] =
                $hash !== '' && is_file($path) && hash_file('sha256', $path) === $hash;
        }

        foreach ($sourceChecks as $label => $passed) {
            $messages[] = ($passed ? 'Verified ' : 'ERROR: ') . $label . '.';
            if (!$passed) {
                $ok = false;
            }
        }
    }

    // If anything after writing fails, restore BOTH production pages.
    if (!$ok) {
        $messages[] = 'Promotion did not certify cleanly. Rolling back BOTH production pages.';
        restore_pair($prodTeam, $prodProfile, $backupDir, $messages);
    } else {
        $success = true;
        $messages[] = 'JOINT PROMOTION CERTIFIED: Team + Profile are Live together.';
        $messages[] = $legacyPagesPresent
            ? 'Legacy standalone email-change pages were left on disk but are no longer used by production Profile.'
            : 'Legacy standalone email-change pages were not both present; production Profile does not depend on them.';
    }
}
?><!doctype html>
