<?php if ($apply): ?>
<div class="card">
<h2>Apply Result</h2>
<p class="<?php echo $success ? 'ok' : 'bad'; ?>"><strong><?php echo $success ? 'SUCCESS' : 'FAILED / ROLLED BACK'; ?></strong></p>
<ul><?php foreach ($messages as $m): ?><li><?php echo ih($m); ?></li><?php endforeach; ?></ul>
<?php if ($success): ?>
<p><a href="/team.php" target="_blank">Open Production Team Page</a></p>
<p><a href="/profile.php" target="_blank">Open Production Profile Page</a></p>
